-- New partner schools start with empty catalogs. Remove the unused Python
-- defaults generated by the historical school-catalog backfill. User-created
-- catalog rows and all rows referenced by business data are preserved.
DELETE FROM "QuestionCourseCategory" AS category
WHERE category."schoolId" IS NOT NULL
  AND category."id" ~ '^qc_[0-9a-f]{24}$'
  AND category."normalizedName" = 'python 程序设计'
  AND NOT EXISTS (
    SELECT 1 FROM "Course" WHERE "questionCategoryId" = category."id"
  )
  AND NOT EXISTS (
    SELECT 1 FROM "Question" WHERE "questionCategoryId" = category."id"
  )
  AND NOT EXISTS (
    SELECT 1 FROM "ExamSession" WHERE "questionCategoryId" = category."id"
  )
  AND NOT EXISTS (
    SELECT 1 FROM "ExamPaperDraft" WHERE "questionCategoryId" = category."id"
  );

DELETE FROM "CourseTemplate" AS template
WHERE template."schoolId" IS NOT NULL
  AND template."id" ~ '^ct_[0-9a-f]{24}$'
  AND template."code" = 'python-programming-v1'
  AND template."isBuiltin" = true
  AND NOT EXISTS (
    SELECT 1 FROM "Course" WHERE "templateId" = template."id"
  );

-- Global historical source rows remain available for recovery of these
-- deterministic copies if a data rollback is needed.
